mapper.select:
SELECT VALUATION
FROM FIN_PRODUCT_VALUATION
WHERE VAL_DATE = TO_DATE(#{valueDate}, 'yyyy-MM-dd') and FINPROD_ID = #{prodId}

SELECT SUM(AMOUNT)
FROM PTL_SEC_POSITION
WHERE CDATE <= TO_DATE(#{tradeDate}, 'yyyy-MM-dd') and FINPROD_ID = #{finprodId}

SELECT A.indexNo, A.FINPROD_ID, A.remainPrinAmt, A.reduceAmt, A.CUSTOM_LEVEL, A.AMT_MIN, A.AMT_MAX, A.TERM_MAX, A.TERM_MIN, to_char(A.vDate, 'yyyy-MM-dd') vDate, to_char(A.mDate, 'yyyy-MM-dd') mDate, A.YIELD*100 YIELD, A.YIELD*100 actYield, A.BASIS, ROUND((A.reduceAmt * A.YIELD*(A.mDate - A.vDate))/A.basisNum, 2) interest FROM ( SELECT CASE WHEN T1.OPERATION_TYPE = #{ISSUE_MODE_02} then to_char(T1.VDATE, 'yyyyMMdd') ELSE t3.BRANCH||'' END indexNo, T1.FINPROD_ID, T6.AMOUNT remainPrinAmt, T6.AMOUNT reduceAmt, DECODE(T1.OPERATION_TYPE, #{ISSUE_MODE_02}, T1.VDATE, #{ISSUE_MODE_01}, t3.VDATE) vDate, CASE WHEN DECODE(T1.OPERATION_TYPE, #{ISSUE_MODE_02}, T1.MDATE, #{ISSUE_MODE_01}, t3.MDATE) < TO_DATE(#{tradeDate}, 'yyyy-MM-dd') THEN DECODE(T1.OPERATION_TYPE, #{ISSUE_MODE_02}, T1.MDATE, #{ISSUE_MODE_01}, t3.MDATE) ELSE TO_DATE(#{tradeDate}, 'yyyy-MM-dd') END mDate, T2.CUSTOM_LEVEL, T2.AMT_MIN, T2.AMT_MAX, T2.TERM_MAX, T2.TERM_MIN, T5.YIELD, T5.BASIS, DECODE(T5.BASIS, #{A_365}, 365, 360) basisNum FROM FIN_PRODUCT T1 LEFT JOIN PRD_LAYER_PARAM T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN PTL_SEC_POSITION T6 ON T3.FINPROD_ID = T6.FINPROD_ID AND T3.BRANCH = T6.BRANCH AND T6.CDATE <= TO_DATE(#{tradeDate}, 'yyyy-MM-dd') LEFT JOIN (select a1.finprod_id, a1.BASIS, a1.branch, a1.YIELD, row_number() over(partition by a1.finprod_id, a1.branch order by EFF_DATE desc) ro from FIN_CASH_CALC_RULE A1 left join FIN_CASH_INFO B1 on A1.CASH_ID = B1.CASH_ID where B1.FINPROD_ID = #{finprodId} and B1.CASH_TYPE_1 = #{CT_02} and B1.CASH_TYPE_2 = #{C02}) T5 on T6.BRANCH = T5.branch and T5.ro = 1 and T1.finprod_id = T5.finprod_id
WHERE T1.P_FINPROD_ID = #{finprodId}
WHERE T1.FINPROD_ID = #{finprodId}
AND T6.AMOUNT > 0 AND DECODE(T1.OPERATION_TYPE, #{ISSUE_MODE_02}, T1.VDATE, #{ISSUE_MODE_01}, t3.VDATE) <= TO_DATE(#{tradeDate}, 'yyyy-MM-dd') ) A

SELECT A.indexNo, A.FINPROD_ID, A.prinAmt, A.FEE_NAME, A.FEE_TYPE, to_char(A.vDate, 'yyyy-MM-dd') vDate, to_char(A.mDate, 'yyyy-MM-dd') mDate, A.YIELD*100 YIELD, A.FEE_ID, A.YIELD*100 actYield, A.BASIS, A.CASH_ID, ROUND((A.prinAmt * A.YIELD*(A.mDate - A.vDate))/A.basisNum, 2) feeAmt FROM ( SELECT CASE WHEN T1.OPERATION_TYPE = #{ISSUE_MODE_02} then to_char(T1.VDATE, 'yyyyMMdd') ELSE t3.BRANCH||'' END indexNo, T1.FINPROD_ID, T6.AMOUNT prinAmt, T7.FEE_NAME, T4.CASH_TYPE_2 FEE_TYPE, CASE WHEN t2.MDATE is not null and DECODE(T1.OPERATION_TYPE, #{ISSUE_MODE_02}, T1.VDATE, #{ISSUE_MODE_01}, t3.VDATE) > t2.MDATE THEN DECODE(T1.OPERATION_TYPE, #{ISSUE_MODE_02}, T1.VDATE, #{ISSUE_MODE_01}, t3.VDATE) ELSE nvl(t2.MDATE, DECODE(T1.OPERATION_TYPE, #{ISSUE_MODE_02}, T1.VDATE, #{ISSUE_MODE_01}, t3.VDATE)) END vDate, CASE WHEN DECODE(T1.OPERATION_TYPE, #{ISSUE_MODE_02}, T1.MDATE, #{ISSUE_MODE_01}, t3.MDATE) < TO_DATE(#{tradeDate}, 'yyyy-MM-dd') THEN DECODE(T1.OPERATION_TYPE, #{ISSUE_MODE_02}, T1.MDATE, #{ISSUE_MODE_01}, t3.MDATE) ELSE TO_DATE(#{tradeDate}, 'yyyy-MM-dd') END mDate, T7.FEE_ID, T5.BASIS, T5.YIELD, t5.CASH_ID, DECODE(T5.BASIS, #{A_365}, 365, 360) basisNum FROM FIN_PRODUCT T1 LEFT JOIN FIN_TRADE_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL T2 ON T2.FINPROD_ID = T1.FINPROD_ID AND T2.BRANCH = T3.BRANCH AND T2.BUSI_TYPE=#{FINPROD19} AND T2.PS = #{C11} AND T2.IS_CLEAN=#{YES} LEFT JOIN FIN_CASH_INFO T4 ON T1.FINPROD_ID = T4.FINPROD_ID AND T3.BRANCH = T4.BRANCH AND T4.CASH_TYPE_2 <> #{C04} AND T4.CASH_TYPE_1 = #{CT_03} LEFT JOIN FIN_CASH_CALC_RULE T5 ON T4.CASH_ID = T5.CASH_ID AND T5.FINPROD_ID = T1.FINPROD_ID AND T5.EFF_DATE <= DECODE(T1.OPERATION_TYPE, #{ISSUE_MODE_02}, T1.VDATE, #{ISSUE_MODE_01}, t3.VDATE) LEFT JOIN PTL_SEC_POSITION T6 ON T3.FINPROD_ID = T6.FINPROD_ID AND T3.BRANCH = T6.BRANCH AND T6.CDATE = TO_DATE(#{tradeDate}, 'yyyy-MM-dd') AND T6.HODING_TYPE=#{HT03} LEFT JOIN MST_FEEINFO T7 ON T4.FEE_ID = T7.FEE_ID
WHERE T1.P_FINPROD_ID = #{finprodId}
WHERE T1.FINPROD_ID = #{finprodId}
AND T6.AMOUNT > 0 AND DECODE(T1.OPERATION_TYPE, #{ISSUE_MODE_02}, T1.VDATE, #{ISSUE_MODE_01}, t3.VDATE) <= TO_DATE(#{tradeDate}, 'yyyy-MM-dd') AND NOT EXISTS (SELECT 1 FROM FIN_CASH_CALC_RULE FCCR WHERE T4.CASH_ID = FCCR.CASH_ID AND FCCR.FINPROD_ID = T1.FINPROD_ID AND FCCR.EFF_DATE <= DECODE(T1.OPERATION_TYPE, #{ISSUE_MODE_02}, T1.VDATE, #{ISSUE_MODE_01}, t3.VDATE) AND FCCR.EFF_DATE > T5.EFF_DATE ) ) A

SELECT FINPROD_ID id, concat(FINPROD_MARKET_ID, concat(':', NVL(FINPROD_ABBR, FINPROD_NAME))) text, FINPROD_ID object FROM FIN_PRODUCT
(P_FINPROD_ID is null or P_FINPROD_ID = '') and PROFIT_TYPE = #{PROFIT_TYPE}
and ( FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND FINPROD_TYPE2 = #{FINPROD_TYPE}
order by FINPROD_MARKET_ID
